class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        INF_NEG = -10 ** 18          # sentinel for impossible states
        m, n = len(coins), len(coins[0])
        # dp[i][j][k]  (k = 0,1,2)
        dp = [[[-10 ** 18] * 3 for _ in range(n)] for __ in range(m)]

        # initialise (0,0)
        v0 = coins[0][0]
        dp[0][0][0] = v0                     # take the value (maybe negative)
        if v0 < 0:
            dp[0][0][1] = 0                  # neutralise the robber

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue    # already initialised
                cur = [INF_NEG] * 3
                v = coins[i][j]

                # collect predecessor DP rows
                preds = []
                if i > 0:
                    preds.append(dp[i - 1][j])
                if j > 0:
                    preds.append(dp[i][j - 1])

                for pred in preds:
                    for used in range(3):
                        prev_val = pred[used]
                        if prev_val == INF_NEG:
                            continue
                        if v >= 0:
                            # normal cell
                            cand = prev_val + v
                            if cand > cur[used]:
                                cur[used] = cand
                        else:
                            # robber, do NOT neutralise
                            cand = prev_val + v
                            if cand > cur[used]:
                                cur[used] = cand
                            # robber, neutralise if possible
                            if used + 1 < 3:
                                if prev_val > cur[used + 1]:
                                    cur[used + 1] = prev_val
                dp[i][j] = cur

        final = dp[m - 1][n - 1]
        return max(final)   # max over k = 0,1,2

