class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        cnt = {}          # maps value -> number of windows of size k containing it

        # slide a window of length k over the array
        for start in range(n - k + 1):
            window = nums[start:start + k]
            distinct = set(window)          # each value counted once per window
            for v in distinct:
                cnt[v] = cnt.get(v, 0) + 1

        # find the largest value that appears in exactly one window
        answer = -1
        for v, c in cnt.items():
            if c == 1 and v > answer:
                answer = v

        return answer

