    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # start index of the candidate block
        for i in range(n - k + 1):
            j = i + k - 1  # inclusive end index

            # ---------- condition 1: all characters equal ----------
            # quick reject if first and last differ
            if s[i] != s[j]:
                continue
            # verify every character inside the block equals s[i]
            uniform = True
            for p in range(i, j + 1):
                if s[p] != s[i]:
                    uniform = False
                    break
            if not uniform:
                continue

            # ---------- condition 2: left neighbour different ----------
            if i > 0 and s[i - 1] == s[i]:
                continue

            # ---------- condition 3: right neighbour different ----------
            if j + 1 < n and s[j + 1] == s[i]:
                continue

            # all conditions satisfied
            return True

        # no suitable block found
        return False

