class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold >= 1, therefore out-degree restriction never blocks feasibility
        max_w = max(w for _, _, w in edges)

        # adjacency list builder for a given weight limit
        def feasible(limit: int) -> bool:
            # reversed graph: edge u -> v becomes v -> u
            rev_adj = [[] for _ in range(n)]
            for a, b, w in edges:
                if w <= limit:
                    rev_adj[b].append(a)   # reverse direction
            # BFS from node 0
            q = deque([0])
            visited = [False] * n
            visited[0] = True
            cnt = 1
            while q:
                cur = q.popleft()
                for nxt in rev_adj[cur]:
                    if not visited[nxt]:
                        visited[nxt] = True
                        cnt += 1
                        q.append(nxt)
            return cnt == n

        lo, hi = 1, max_w
        ans = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                ans = mid
                hi = mid - 1      # try smaller limit
            else:
                lo = mid + 1      # need larger limit
        return ans

