    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10 ** 18                     # larger than any possible answer
        # dp[cl][cr]  : current outer colours (left, right)
        dp = [[INF] * 3 for _ in range(3)]

        # ---- initialise first (outermost) pair ----
        for cl in range(3):
            for cr in range(3):
                if cl == cr:
                    continue              # symmetry constraint
                dp[cl][cr] = cost[0][cl] + cost[n - 1][cr]

        half = n // 2
        # ---- process inner pairs ----
        for i in range(1, half):
            ndp = [[INF] * 3 for _ in range(3)]
            left_idx = i
            right_idx = n - 1 - i
            for prevL in range(3):
                for prevR in range(3):
                    cur_val = dp[prevL][prevR]
                    if cur_val == INF:
                        continue
                    for cl in range(3):
                        if cl == prevL:          # left adjacency
                            continue
                        for cr in range(3):
                            if cr == prevR:      # right adjacency
                                continue
                            if cl == cr:         # symmetry
                                continue
                            new_cost = (cur_val +
                                        cost[left_idx][cl] +
                                        cost[right_idx][cr])
                            if new_cost < ndp[cl][cr]:
                                ndp[cl][cr] = new_cost
            dp = ndp

        # ---- answer is the best value of the last layer ----
        ans = INF
        for cl in range(3):
            for cr in range(3):
                if dp[cl][cr] < ans:
                    ans = dp[cl][cr]
        return ans

