class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # collect values for each diagonal (key = r + c)
        diag = defaultdict(list)
        for r in range(n):
            for c in range(n):
                diag[r + c].append(grid[r][c])

        # Determine the sorting direction for each diagonal
        # and sort in place
        for d, values in diag.items():
            # locate the start cell of this diagonal
            if d < n:               # starts on the left border
                start_r, start_c = d, 0
            else:                   # starts on the bottom border
                start_r, start_c = n - 1, d - (n - 1)

            # bottom‑left triangle condition
            if start_r >= start_c:
                values.sort(reverse=True)   # descending
            else:
                values.sort()                # ascending

        # write sorted values back
        for d in diag:
            # recompute start cell (same logic as above)
            if d < n:
                r, c = d, 0
            else:
                r, c = n - 1, d - (n - 1)

            # pop from the front of the list (already sorted)
            while 0 <= r < n and 0 <= c < n:
                grid[r][c] = diag[d].pop(0)
                r -= 1          # move north‑west? actually north‑east is (-1,+1)
                c += 1

        return grid

