    def maxFrequency(self, nums: List[int], k: int) -> int:
        # count of original k's
        baseline = 0
        for a in nums:
            if a == k:
                baseline += 1

        best_add = 0          # best number of new k's we can create
        cur_max = 0           # maximal frequency inside current k‑free segment
        cnt = [0] * 51        # values are in [1,50]

        for a in nums:
            if a == k:
                # segment ends
                if cur_max > best_add:
                    best_add = cur_max
                # reset for next segment
                cnt = [0] * 51
                cur_max = 0
            else:
                cnt[a] += 1
                if cnt[a] > cur_max:
                    cur_max = cnt[a]

