    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1                     # length of the required word

        # characters of the word, None = not decided yet
        ch = [None] * L
        # True for positions forced by a 'T' condition
        fixed = [False] * L

        # ---------- 1. apply all 'T' constraints ----------
        for i, flag in enumerate(str1):
            if flag == 'T':
                for k in range(m):
                    pos = i + k
                    need = str2[k]
                    if ch[pos] is None:
                        ch[pos] = need
                        fixed[pos] = True
                    elif ch[pos] != need:          # contradiction
                        return ""

        # ---------- 2. fill the rest with the smallest letter ----------
        for pos in range(L):
            if ch[pos] is None:
                ch[pos] = 'a'

        # ---------- 3. satisfy all 'F' constraints ----------
        for i, flag in enumerate(str1):
            if flag != 'F':
                continue

            # does the substring already equal str2 ?
            equal = True
            for k in range(m):
                if ch[i + k] != str2[k]:
                    equal = False
                    break

            if not equal:
                continue        # already satisfied

            # need to break it: pick the rightmost mutable position
            j = -1
            for pos in range(i + m - 1, i - 1, -1):
                if not fixed[pos]:
                    j = pos
                    break
            if j == -1:          # no mutable place -> impossible
                return ""

            # smallest character different from the required one
            need = str2[j - i]
            ch[j] = 'a' if need != 'a' else 'b'

        # ---------- 4. build and return the answer ----------
        return ''.join(ch)

