class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # distance on circular alphabet
        def char_dist(a: str, b: str) -> int:
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        # dp[i][j] is a bytearray of length (k+1)
        dp: List[List[bytearray]] = [[bytearray(k + 1) for _ in range(n)]
                                      for _ in range(n)]

        # length 1 substrings
        for i in range(n):
            for c in range(k + 1):
                dp[i][i][c] = 1      # a single character palindrome

        # increasing substring length
        for length in range(2, n + 1):
            for i in range(0, n - length + 1):
                j = i + length - 1
                pair_cost = char_dist(s[i], s[j])

                # access to neighbouring subproblems
                dp_i1_j = dp[i + 1][j]        # length-1, start moved right
                dp_i_j1 = dp[i][j - 1]        # length-1, end moved left
                dp_i1_j1 = dp[i + 1][j - 1]   # length-2, both moved

                cur = dp[i][j]                # the bytearray we are filling
                for c in range(k + 1):
                    best = dp_i1_j[c]
                    if dp_i_j1[c] > best:
                        best = dp_i_j1[c]

                    if c >= pair_cost:
                        cand = dp_i1_j1[c - pair_cost] + 2
                        if cand > best:
                            best = cand

                    cur[c] = best   # store result for (i,j,c)

        # result for the whole string with at most k operations
        return dp[0][n - 1][k]

