    def longestPalindrome(self, s: str, t: str) -> int:
        # Helper to generate all substrings (including empty) of a string
        def substrings(st: str):
            n = len(st)
            # empty substring first
            yield ""
            for i in range(n):
                # build gradually to avoid slicing many times
                cur = ""
                for j in range(i, n):
                    cur += st[j]          # st[i:j+1]
                    yield cur

        best = 0
        # enumerate all substrings of s and t
        for sub_s in substrings(s):
            for sub_t in substrings(t):
                cand = sub_s + sub_t
                # quick length check: if its length <= current best, skip palindrome test
                if len(cand) <= best:
                    continue
                if cand == cand[::-1]:          # palindrome test
                    best = len(cand)
        return best

