class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        # ---------------------------------------------------------
        # digit DP returning count of beautiful numbers ≤ x
        # ---------------------------------------------------------
        from functools import lru_cache

        def count_upto(x: int) -> int:
            if x <= 0:
                return 0
            digits = list(map(int, str(x)))
            n = len(digits)

            @lru_cache(maxsize=None)
            def dfs(pos: int, s: int, p: int, started: bool, tight: bool) -> int:
                """return number of ways for suffix starting at pos"""
                if pos == n:                     # all positions processed
                    if not started:              # the number 0, ignore
                        return 0
                    return 1 if p % s == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    ntight = tight and (d == limit)
                    if not started and d == 0:
                        # still skipping leading zeros
                        total += dfs(pos + 1, s, p, False, ntight)
                    else:
                        ns = s + d
                        np = p * d                # if p == 0 stays 0
                        total += dfs(pos + 1, ns, np, True, ntight)
                return total

            # start with empty prefix: sum = 0, product = 1 (neutral)
            return dfs(0, 0, 1, False, True)

        # answer for the required interval
        return count_upto(r) - count_upto(l - 1)

