class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # 1. turn each row into a set of distinct values
        sets = [set(row) for row in properties]

        # 2. build adjacency list
        adj = [[] for _ in range(n)]
        for i in range(n):
            si = sets[i]
            for j in range(i + 1, n):
                sj = sets[j]
                # iterate over the smaller set for efficiency
                if len(si) < len(sj):
                    small, large = si, sj
                else:
                    small, large = sj, si
                common = sum(1 for val in small if val in large)
                if common >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # 3. DFS to count components
        visited = [False] * n
        components = 0

        def dfs(v: int):
            stack = [v]
            visited[v] = True
            while stack:
                cur = stack.pop()
                for nb in adj[cur]:
                    if not visited[nb]:
                        visited[nb] = True
                        stack.append(nb)

        for i in range(n):
            if not visited[i]:
                components += 1
                dfs(i)

        return components

