def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it))
    X = int(next(it))

    foods = []
    for _ in range(N):
        v = int(next(it))
        a = int(next(it))
        c = int(next(it))
        foods.append((v, a, c))

    # dp[cal] = list of (s1, s2, s3) triples, Pareto-optimal (none dominates another)
    dp = [[] for _ in range(X + 1)]
    dp[0].append((0, 0, 0))

    # helper to insert a triple into a list while keeping it Pareto-optimal
    def insert_state(lst, new_state):
        n1, n2, n3 = new_state
        # if an existing state dominates the new one, discard it
        for a, b, c in lst:
            if a >= n1 and b >= n2 and c >= n3:
                return
        # otherwise remove any states that are dominated by the new one
        i = 0
        while i < len(lst):
            a, b, c = lst[i]
            if n1 >= a and n2 >= b and n3 >= c:
                lst.pop(i)
            else:
                i += 1
        lst.append(new_state)

    for v, a, cal in foods:
        # iterate calories descending (0‑1 knapsack)
        for cur in range(X - cal, -1, -1):
            if not dp[cur]:
                continue
            nxt = cur + cal
            lst_cur = dp[cur]
            lst_nxt = dp[nxt]
            for s1, s2, s3 in lst_cur:
                if v == 1:
                    ns = (s1 + a, s2, s3)
                elif v == 2:
                    ns = (s1, s2 + a, s3)
                else:
                    ns = (s1, s2, s3 + a)
                insert_state(lst_nxt, ns)

    ans = 0
    for cal in range(X + 1):
        for s1, s2, s3 in dp[cal]:
            cur_min = s1
            if s2 < cur_min:
                cur_min = s2
            if s3 < cur_min:
