def upd(node):
    if node:
        node.size = 1 + (node.left.size if node.left else 0) + (node.right.size if node.right else 0)

def split(root, k):
    """return (L, R) where L has first k elements (0 <= k <= size)"""
    if not root:
        return (None, None)
    left_sz = root.left.size if root.left else 0
    if k <= left_sz:
        # split left subtree
        l, r = split(root.left, k)
        root.left = r
        upd(root)
        return (l, root)
    else:
        # split right subtree
        l, r = split(root.right, k - left_sz - 1)
        root.right = l
        upd(root)
        return (root, r)

def merge(a, b):
